export function shortcutAction(e,{mode,editable=false,dialog=false,button=false}={}){if(editable||dialog||e.isComposing||e.altKey)return null;const key=e.key.toLowerCase(),command=e.ctrlKey||e.metaKey;if(command){if(key==='s')return 'save';if(key==='z')return e.shiftKey?'redo':'undo';if(key==='y')return 'redo';return null}if(key==='?'||key==='f1')return 'help';if(key==='1')return '3d';if(key==='2')return '2d';if(key==='3')return 'follow';const tools={b:'paint',e:'erase',g:'fill',i:'pick',h:'pan'};if(tools[key])return 'tool:'+tools[key];if(key==='0')return 'fit';if(mode==='3d')return null;if(['arrowleft','arrowright','arrowup','arrowdown'].includes(key))return 'pan:'+key.slice(5);if(key==='+'||key==='=')return 'zoomIn';if(key==='-'||key==='_')return 'zoomOut';if(key===' '&&!button)return 'holdPan';if(mode==='follow'){if(key==='[')return 'prevRow';if(key===']')return 'nextRow';if(key==='c')return 'centerRow';if(key==='enter'&&!button)return 'completeRow'}return null}
